"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["8852"],{72250(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.formulario_portavel.ocorrencia_invalida","status":422,"titulo":"Ocorr\xeancia de grupo sem identidade pr\xf3pria no grupo"},"descricao":{"codigo":"uniplus.formulario_portavel.ocorrencia_invalida","requisitos":["UNI-REQ-0069"],"oQueAconteceu":["A avalia\xe7\xe3o de um formul\xe1rio sem cadastro confere as regras de um formul\xe1rio apresentado contra respostas simuladas, sem gravar nada nem registrar o conte\xfado enviado. Em `grupos`, um grupo repet\xedvel traz uma ocorr\xeancia sem `id`, com `id` vazio ou s\xf3 com espa\xe7os, nula, ou com um `id` j\xe1 usado por outra ocorr\xeancia do mesmo grupo. Cada ocorr\xeancia precisa de identidade pr\xf3pria, porque \xe9 por ela que o documento exigido por membro, como na composi\xe7\xe3o familiar, se liga \xe0 ocorr\xeancia (UNI-REQ-0069). O `id` \xe9 opcional no JSON: a aus\xeancia chega \xe0 confer\xeancia e responde 422 com o c\xf3digo desta p\xe1gina. A mensagem \xe9 \\"Cada ocorr\xeancia do grupo precisa de uma identidade pr\xf3pria, que n\xe3o se repita no grupo.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `grupos.\\\\{c\xf3digo do grupo\\\\}[i].id`, em que `i` \xe9 a posi\xe7\xe3o da ocorr\xeancia. Cada ocorr\xeancia com problema gera a pr\xf3pria entrada, e a recusa do envio simulado (fuso e instante) vem na mesma lista. Nada \xe9 gravado. As regras s\xf3 s\xe3o avaliadas quando a lista est\xe1 vazia: as recusas das regras, como a de [estrutura inv\xe1lida](/erros/uniplus.formulario_portavel.estrutura_invalida), s\xf3 aparecem depois que as ocorr\xeancias est\xe3o corretas.","O mesmo problema na pr\xe9-visualiza\xe7\xe3o de um modelo de formul\xe1rio tem o c\xf3digo [ocorr\xeancia simulada sem identidade no modelo](/erros/uniplus.configuracao.modelo_formulario.ocorrencia_simulada_invalida)."],"comoResolver":["Informe um identificador distinto para cada ocorr\xeancia de cada grupo repet\xedvel da simula\xe7\xe3o e repita a avalia\xe7\xe3o."],"ondeAparece":["Avalia\xe7\xe3o de formul\xe1rio sem cadastro"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Formulario portavel"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);